"use server";

import { revalidatePath } from "next/cache";
import { db } from "@/lib/db";
import { requireAuth, requireMember } from "@/lib/auth";
import { toDateOnly } from "@/lib/utils";
import {
  personCreateSchema,
  personUpdateSchema,
  type PersonCreateInput,
  type PersonUpdateInput,
} from "@/schemas/person";

export async function getPersons(options?: {
  search?: string;
  status?: string;
  gender?: string;
  limit?: number;
  offset?: number;
}) {
  const { search, status, gender, limit = 50, offset = 0 } = options || {};

  const where: {
    OR?: { firstName?: object; lastName?: object; maidenName?: object }[];
    isLiving?: boolean;
    gender?: "MALE" | "FEMALE" | "OTHER" | "PREFER_NOT_TO_SAY";
  } = {};

  if (search) {
    where.OR = [
      { firstName: { contains: search, mode: "insensitive" as const } },
      { lastName: { contains: search, mode: "insensitive" as const } },
      { maidenName: { contains: search, mode: "insensitive" as const } },
    ];
  }

  if (status === "living") {
    where.isLiving = true;
  } else if (status === "deceased") {
    where.isLiving = false;
  }

  if (
    gender &&
    ["MALE", "FEMALE", "OTHER", "PREFER_NOT_TO_SAY"].includes(gender)
  ) {
    where.gender = gender as "MALE" | "FEMALE" | "OTHER" | "PREFER_NOT_TO_SAY";
  }

  const [persons, total] = await Promise.all([
    db.person.findMany({
      where,
      orderBy: [{ lastName: "asc" }, { firstName: "asc" }],
      take: limit,
      skip: offset,
      include: {
        relationshipsFrom: {
          include: { relatedPerson: true },
        },
        relationshipsTo: {
          include: { person: true },
        },
      },
    }),
    db.person.count({ where }),
  ]);

  return { persons, total };
}

export async function getPerson(id: string) {
  return db.person.findUnique({
    where: { id },
    include: {
      relationshipsFrom: {
        include: { relatedPerson: true },
      },
      relationshipsTo: {
        include: { person: true },
      },
      createdBy: {
        select: { id: true, name: true, email: true },
      },
    },
  });
}

export async function createPerson(input: PersonCreateInput) {
  const user = await requireMember();
  const validated = personCreateSchema.parse(input);

  const person = await db.person.create({
    data: {
      firstName: validated.firstName,
      lastName: validated.lastName,
      maidenName: validated.maidenName,
      dateOfBirth: validated.dateOfBirth
        ? toDateOnly(validated.dateOfBirth)
        : null,
      dateOfPassing: validated.dateOfPassing
        ? toDateOnly(validated.dateOfPassing)
        : null,
      birthPlace: validated.birthPlace,
      nativePlace: validated.nativePlace,
      gender: validated.gender,
      bio: validated.bio,
      email: validated.email || null,
      phone: validated.phone,
      currentAddress: validated.currentAddress ?? undefined,
      workAddress: validated.workAddress ?? undefined,
      profession: validated.profession,
      employer: validated.employer,
      socialLinks: validated.socialLinks ?? undefined,
      isLiving: validated.isLiving,
      createdById: user.id,
    },
  });

  revalidatePath("/people");
  revalidatePath("/tree");

  return { success: true, person };
}

export async function updatePerson(id: string, input: PersonUpdateInput) {
  const user = await requireMember();
  const validated = personUpdateSchema.parse(input);

  const existing = await db.person.findUnique({ where: { id } });
  if (!existing) {
    throw new Error("Person not found");
  }

  const linkedUser = await db.user.findUnique({
    where: { personId: id },
  });

  const isOwnProfile = linkedUser?.id === user.id;
  const isAdmin = user.role === "ADMIN";

  if (!isOwnProfile && !isAdmin) {
    throw new Error("You can only edit your own profile or request changes");
  }

  const updateData: Parameters<typeof db.person.update>[0]["data"] = {};
  if (validated.firstName !== undefined)
    updateData.firstName = validated.firstName;
  if (validated.lastName !== undefined)
    updateData.lastName = validated.lastName;
  if (validated.maidenName !== undefined)
    updateData.maidenName = validated.maidenName;
  if (validated.dateOfBirth !== undefined)
    updateData.dateOfBirth = validated.dateOfBirth
